import{_ as r,o,c as s,a2 as d}from"./chunks/framework.CHeM0PsO.js";const c=JSON.parse('{"title":"01a · 目标人群与竞品","description":"","frontmatter":{},"headers":[],"relativePath":"lab/shuangyu-fries/01a-audience-competitors.md","filePath":"lab/shuangyu-fries/01a-audience-competitors.md","lastUpdated":1787456457000}'),a={name:"lab/shuangyu-fries/01a-audience-competitors.md"};function n(g,t,e,l,h,p){return o(),s("div",null,[...t[0]||(t[0]=[d(`<h1 id="_01a-·-目标人群与竞品" tabindex="-1">01a · 目标人群与竞品 <a class="header-anchor" href="#_01a-·-目标人群与竞品" aria-label="Permalink to &quot;01a · 目标人群与竞品&quot;">​</a></h1><blockquote><p>阶段 1 · 提案支撑 ｜ 2026-08-06 ｜ <strong>内部推演，不对客</strong></p></blockquote><div class="danger custom-block"><p class="custom-block-title">这是纸上推演，不是调研结论</p><p>本文全部结论由「产品形态倒推 + 品类常识」生成，不是调研。</p><p><strong>不要在没有标注来源的情况下把本文内容写进对客文档。</strong> 需要对客时，只取标 <strong>A</strong> 的部分，或先完成文末《须核实清单》第 1、2 项。</p></div><div class="warning custom-block"><p class="custom-block-title">2026-08-06 更正：本文初稿的一个前提是错的</p><p>初稿写「客户未提供<strong>任何</strong>人群定位、定价、分销渠道或竞品资料」，并据此把全部人群结论定为 C 级推演。</p><p><strong>实际上客户口头提过人群与竞品</strong>，原话待补入。定价与分销渠道则确实仍未提供。</p><p><strong>影响范围</strong>：第一节（目标人群）与第三节（最重要的一条结论）中所有 C 级判断，在原话补入前<strong>既不能采用、也不能视为已证伪</strong>——详见文末《须核实清单》。</p></div><h2 id="证据分级" tabindex="-1">证据分级 <a class="header-anchor" href="#证据分级" aria-label="Permalink to &quot;证据分级&quot;">​</a></h2><p>每条结论后标注来源，避免推演被误当成事实。</p><table tabindex="0"><thead><tr><th>级</th><th>含义</th><th>可否作为决策依据</th></tr></thead><tbody><tr><td><strong>A</strong></td><td>包装图上可确认的事实，或客户明确告知</td><td>✅ 可以</td></tr><tr><td><strong>B</strong></td><td>品类公开常识，可查证但我方未逐条核实</td><td>🟡 可作参考，引用前抽查</td></tr><tr><td><strong>C</strong></td><td>我方假设</td><td>❌ <strong>须核实后才能用</strong></td></tr></tbody></table><h2 id="为什么现在写这份" tabindex="-1">为什么现在写这份 <a class="header-anchor" href="#为什么现在写这份" aria-label="Permalink to &quot;为什么现在写这份&quot;">​</a></h2><p>提案 <a href="./01-proposal">01</a> 定了核心主张（鲜切主、VF 支撑），但<strong>这个主张目前没有参照物</strong>——「原薯鲜切」比谁强、抢的是谁的份额、说给谁听，三个问题都没答案。</p><div class="warning custom-block"><p class="custom-block-title">缺人群和竞品，主张就只是一句好听的话</p><p>当前项目状态是「全卡在物料」（见 <a href="./">项目首页</a>）。但<strong>人群与竞品这两件事不依赖客户物料</strong>，是等待期里唯一能自主推进、且直接加固提案地基的工作。</p><p>更要紧的是：文末第 1 项核实一旦结果为「无差异」，<strong>决议 ① 就要推翻</strong>。这个风险现在不查，会在分镜阶段以更贵的方式暴露。</p></div><hr><h2 id="一、目标人群" tabindex="-1">一、目标人群 <a class="header-anchor" href="#一、目标人群" aria-label="Permalink to &quot;一、目标人群&quot;">​</a></h2><h3 id="_1-先从形态倒推约束" tabindex="-1">1. 先从形态倒推约束 <a class="header-anchor" href="#_1-先从形态倒推约束" aria-label="Permalink to &quot;1. 先从形态倒推约束&quot;">​</a></h3><p>不猜人群，先看产品自己限定了什么。</p><table tabindex="0"><thead><tr><th>产品事实</th><th>推出的约束</th><th>级</th></tr></thead><tbody><tr><td><strong>46g 单人份</strong></td><td>一次吃完的量，<strong>不是分享装、不是囤货装</strong></td><td>A</td></tr><tr><td><strong>纸杯 + 铝箔 + 塑料盖</strong></td><td>包材成本明显高于枕式袋，<strong>同克重零售价必然高于袋装薯片</strong></td><td>A → C</td></tr><tr><td><strong>杯身可立、可单手持</strong></td><td>适合桌面、通勤、单手场景；不适合沙发前抓着吃</td><td>A</td></tr><tr><td><strong>条状（薯条形态）</strong></td><td>不掉渣、不碎屑，比薯片更适合办公桌与公共场合</td><td>A</td></tr><tr><td><strong>常温预包装、无热气</strong></td><td>没有「刚出锅」的信息量，食欲感只能靠声音和断面</td><td>A</td></tr><tr><td><strong>抖音 + 电商详情页</strong></td><td>客户口头告知的渠道判断</td><td>A</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">这几条指向同一件事</p><p><strong>单人、即时、场景化消费，不是家庭零食柜。</strong></p><p>杯装带来的溢价，必须由「场景便利」兑现——不能由「更好吃」或「更健康」兑现，后者一个没有证据、一个不能说。</p></div><h3 id="_2-三个候选人群与取舍" tabindex="-1">2. 三个候选人群与取舍 <a class="header-anchor" href="#_2-三个候选人群与取舍" aria-label="Permalink to &quot;2. 三个候选人群与取舍&quot;">​</a></h3><table tabindex="0"><thead><tr><th></th><th>人群</th><th>判断</th></tr></thead><tbody><tr><td><strong>A</strong></td><td><strong>18–30 岁都市学生 / 初入职场者</strong>，便利店与零食集合店随手买</td><td>✅ <strong>建议为核心</strong></td></tr><tr><td><strong>B</strong></td><td>25–40 岁家庭采购者，为孩子 / 零食柜囤货</td><td>❌ 排除</td></tr><tr><td><strong>C</strong></td><td>健康意识型轻食人群，为「低温油炸」买单</td><td>🟡 承接，但<strong>不能作为传播对象</strong></td></tr></tbody></table><p><strong>B 为什么排除</strong>（C 级推演）：46g 杯装的单位克重价格在薯类零食里偏高，囤货客对价格敏感，且杯装占空间、不适合多件囤放。<strong>这个包装形态本身就把囤货客筛掉了</strong>——广告再去够他，两头不讨好。</p><p><strong>C 为什么只能承接、不能喊话</strong>：这群人是最愿意为 VF 付溢价的，但 <a href="./01-proposal">提案第三节</a> 的内容边界已经写死——「更健康 / 低脂 / 0 负担」一律不能说。</p><div class="tip custom-block"><p class="custom-block-title">承接与喊话的区别</p><p><strong>能被吸引，不能被喊话。</strong></p><p>做法是把工艺展示做扎实（多孔断面、80~90℃、脱油离心），让这群人自己认出来。这与 <a href="/cases/case-04-vf-fries-crisp">案例 04</a> 的核心结论同源：<strong>你替他下的结论他不信，他自己下的结论他才信。</strong></p></div><h3 id="_3-核心人群画像" tabindex="-1">3. 核心人群画像 <a class="header-anchor" href="#_3-核心人群画像" aria-label="Permalink to &quot;3. 核心人群画像&quot;">​</a></h3><blockquote><p><strong>一个在便利店货架前站了三秒的人。</strong></p></blockquote><p>以下除标注外均为 <strong>C 级</strong>，待客户校准。</p><table tabindex="0"><thead><tr><th>维度</th><th>推演</th></tr></thead><tbody><tr><td><strong>年龄</strong></td><td>18–28，学生 + 工作 1–3 年</td></tr><tr><td><strong>性别倾向</strong></td><td>略偏女性（杯装、番茄味、可复盖均偏女性偏好），但<strong>不是女性专属产品</strong>，不建议做成女性向调性</td></tr><tr><td><strong>购买场景</strong></td><td>便利店 / 零食集合店 / 校园超市；线上以尝鲜首单为主，复购靠线下</td></tr><tr><td><strong>消费场景</strong></td><td>下午三点的工位、自习间隙、通勤路上、宿舍夜聊</td></tr><tr><td><strong>决策依据</strong></td><td><strong>形态新鲜感 &gt; 口味 &gt; 品牌</strong>。新品无品牌资产可依（A：未上市）</td></tr><tr><td><strong>单次决策时间</strong></td><td>3–5 秒</td></tr><tr><td><strong>反对意见</strong></td><td>「又是油炸的」「这么小一杯还这么贵」</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">决策时间这一条直接支撑了 B 片的结构</p><p>3–5 秒的货架决策 = 信息流里 1–2 秒的划走判断。</p><p><strong>这是 B 片必须第一帧就撕封口的真实理由</strong>——不是因为撕封口好看，是因为没有第二次机会。<a href="./01-proposal">提案第二节</a> 的这条设定，现在有了人群侧的依据。</p></div><p><strong>两条反对意见分别在哪回答</strong>：</p><table tabindex="0"><thead><tr><th>反对意见</th><th>在哪回答</th><th>备注</th></tr></thead><tbody><tr><td>「又是油炸的」</td><td><strong>脱油离心工序</strong></td><td>工序陈述，不是营养宣称，合规。见 <a href="./00-brief">00-brief 工艺资料裁定</a></td></tr><tr><td>「这么小还这么贵」</td><td><strong>广告回答不了</strong></td><td>这是定价与渠道的问题。片子里试图解决它会变成自证式辩解，反而坐实了「贵」</td></tr></tbody></table><h3 id="_4-一个需要推翻的既有假设" tabindex="-1">4. 一个需要推翻的既有假设 <a class="header-anchor" href="#_4-一个需要推翻的既有假设" aria-label="Permalink to &quot;4. 一个需要推翻的既有假设&quot;">​</a></h3><p><a href="./00-brief">00-brief</a> 写过：「可复盖 →『吃不完盖上』是一个真实使用场景」。</p><p><strong>这条在 46g 规格下大概率不成立</strong>（C）。46g 是一次吃完的量，「吃不完」在这个克重上不是高频场景。</p><p>可复盖的真实价值更可能是：</p><ul><li><strong>放进包里不撒</strong>（通勤、上课路上）</li><li><strong>放在工位上不落灰</strong>（同一天内分几次吃完）</li></ul><div class="warning custom-block"><p class="custom-block-title">对创意的直接影响</p><p>如果 B 片想用「盖回去」作收尾动作，理由要从**「吃不完」换成「随身带」**——否则观众会觉得不真实（46g 谁吃不完？），一个不真实的细节会带走整支片子的可信度。</p></div><hr><h2 id="二、竞品" tabindex="-1">二、竞品 <a class="header-anchor" href="#二、竞品" aria-label="Permalink to &quot;二、竞品&quot;">​</a></h2><h3 id="_1-四层竞品圈" tabindex="-1">1. 四层竞品圈 <a class="header-anchor" href="#_1-四层竞品圈" aria-label="Permalink to &quot;1. 四层竞品圈&quot;">​</a></h3><p>大多数人只看第一层，<strong>真正抢走这几块钱的往往在第三层。</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>① 同形态：杯装 / 罐装 条状薯条</span></span>
<span class="line"><span>   ↓</span></span>
<span class="line"><span>② 同品类：所有休闲薯类零食</span></span>
<span class="line"><span>   ↓</span></span>
<span class="line"><span>③ 同场景：便利店里 5–10 元的单人即食零食  ← 真正的钱包竞争</span></span>
<span class="line"><span>   ↓</span></span>
<span class="line"><span>④ 同叙事：讲工艺 / 讲「轻负担」的零食</span></span></code></pre></div><h3 id="_2-第一层-·-直接竞品-形态高度重合" tabindex="-1">2. 第一层 · 直接竞品（形态高度重合） <a class="header-anchor" href="#_2-第一层-·-直接竞品-形态高度重合" aria-label="Permalink to &quot;2. 第一层 · 直接竞品（形态高度重合）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>竞品</th><th>形态</th><th>与本品的关系</th><th>级</th></tr></thead><tbody><tr><td><strong>卡乐比 じゃがりこ / Jagariko</strong></td><td>塑料杯装、条状薯条</td><td><strong>形态原型，最强对标。</strong> 包装日文副标「カリカリポテトフライ」进一步指向这个参照</td><td>B</td></tr><tr><td><strong>卡乐比 Jagabee / 薯条三兄弟</strong></td><td>盒装 / 袋装粗薯条</td><td>高端进口薯条心智的占位者</td><td>B</td></tr><tr><td><strong>可比克 · 纸罐装</strong></td><td>纸罐薯片（片状）</td><td><strong>国产杯罐装薯类的价格锚</strong>，性价比一侧</td><td>B</td></tr><tr><td><strong>乐事 Stax 罐装 / 品客 Pringles</strong></td><td>罐装片状</td><td>形态近、内容物不同；占据「罐装薯片」心智</td><td>B</td></tr><tr><td>国产白牌杯装薯条</td><td>杯装条状</td><td>零食集合店与电商大量存在，<strong>数量与价格带未知，需实地扫店</strong></td><td>C</td></tr></tbody></table><div class="danger custom-block"><p class="custom-block-title">日文副标在竞品坐标下，性质变了</p><p>在 <a href="./00-brief">00-brief</a> 里，日文元素被定性为<strong>合规风险</strong>。放进竞品坐标后它还有第二重性质：</p><p><strong>它在向 Jagariko 的心智借力。</strong> 杯装 + 条状 + 日文，三个特征叠在一起，消费者的第一联想几乎必然是那款日本零食。</p><p><strong>这意味着：广告一旦做日式调性，不只是虚假宣传风险，还是在替竞品做教育。</strong></p><p><strong>2026-08-06 更新</strong>：客户已确认日文副标为<strong>纯装饰，与日本无任何关系</strong>。</p><p>这个答案让上面的判断从「建议」升级成了「结论」：</p><blockquote><p><strong>没有实质支撑的日文，只有借力效果，没有背书价值。</strong></p></blockquote><p>它不能证明产品好——因为背后什么都没有；却会把消费者的第一联想推给已有的日式同类产品。<strong>留着它是包装的既成事实，强调它是纯亏。</strong></p><p>由此形成一条执行约束：<strong>包装出镜时不刻意突出日文副标</strong>。已写入 <a href="./02-materials">02 · 物料清单</a> 与 <a href="./">决议 ③</a>。</p></div><h3 id="_3-第三层-·-场景竞品-最容易被忽略的一层" tabindex="-1">3. 第三层 · 场景竞品（最容易被忽略的一层） <a class="header-anchor" href="#_3-第三层-·-场景竞品-最容易被忽略的一层" aria-label="Permalink to &quot;3. 第三层 · 场景竞品（最容易被忽略的一层）&quot;">​</a></h3><p>便利店货架前，这几块钱真正的对手（均 B 级）：</p><table tabindex="0"><thead><tr><th>对手</th><th>它赢在哪</th></tr></thead><tbody><tr><td>小包装坚果 / 每日坚果</td><td>「健康」叙事完整，且<strong>不需要合规辩解</strong></td></tr><tr><td>肉脯、鱼豆腐、鸡胸肉肠</td><td><strong>蛋白质叙事</strong>，占据「吃了不心虚」</td></tr><tr><td>海苔、果蔬脆</td><td>轻负担感 + 女性偏好</td></tr><tr><td>现制饮品的小料 / 关东煮</td><td>同价位、同场景，<strong>而且是热的</strong></td></tr></tbody></table><div class="danger custom-block"><p class="custom-block-title">这一层的战略含义最重要</p><p><strong>本品在「心安理得」这条赛道上是天然劣势方</strong>——它是油炸的，且除了「不油腻」之外的健康话一句都不能说。而对手不但能说，还说得理直气壮。</p><p><strong>所以竞争位不能选在「更健康」，只能选在「口感体验」与「场景新鲜感」。</strong></p><p>这从竞品侧再次印证了 <a href="./">决议 ①</a>：鲜切讲的是<strong>原料与口感</strong>，不是健康——方向是对的。</p></div><h3 id="_4-第四层-·-叙事竞品" tabindex="-1">4. 第四层 · 叙事竞品 <a class="header-anchor" href="#_4-第四层-·-叙事竞品" aria-label="Permalink to &quot;4. 第四层 · 叙事竞品&quot;">​</a></h3><table tabindex="0"><thead><tr><th>叙事</th><th>谁在用</th><th>对本品的意义</th><th>级</th></tr></thead><tbody><tr><td><strong>非油炸 / 烘焙型</strong></td><td>乐事无限烘焙型等</td><td><strong>本品永远不能进这条赛道</strong>（VF 是油炸），且已被占据</td><td>B</td></tr><tr><td><strong>冻干 / 果蔬脆</strong></td><td>三只松鼠、良品铺子等</td><td>工艺叙事的成熟范式，<strong>做法可借鉴，主张不可挪用</strong></td><td>B</td></tr><tr><td><strong>原切 / 鲜切</strong></td><td>部分中高端与进口薯片</td><td><strong>本品要抢的就是这一条</strong></td><td>B</td></tr></tbody></table><hr><h2 id="三、本文最重要的一条结论" tabindex="-1">三、本文最重要的一条结论 <a class="header-anchor" href="#三、本文最重要的一条结论" aria-label="Permalink to &quot;三、本文最重要的一条结论&quot;">​</a></h2><blockquote><p><strong>「原薯鲜切」到底是强差异还是废话，取决于直接竞品是不是鲜切的——而这一条我方目前不知道。</strong></p></blockquote><table tabindex="0"><thead><tr><th>若……</th><th>则「原薯鲜切」是</th><th>创意后果</th></tr></thead><tbody><tr><td>主流杯装条状薯条多为<strong>薯粉 / 薯泥成型</strong></td><td><strong>强差异，主张成立</strong></td><td>决议 ① 站得住，且可以更用力</td></tr><tr><td>主流杯装条状薯条<strong>本来就是鲜切的</strong></td><td><strong>无差异，只是品类基本盘</strong></td><td><strong>主标题要换</strong>，VF 可能要提回主位</td></tr></tbody></table><div class="danger custom-block"><p class="custom-block-title">这是最值钱、也最不确定的一条</p><p>薯<strong>片</strong>品类里「鲜切」是弱差异——乐事本来就是切片的。但<strong>杯装条状薯条是另一个品类</strong>，成型工艺在其中的占比，我方没有把握，<strong>上表两个分支目前都不能排除</strong>。</p><p><strong>核实方法（不依赖客户，我方可自行完成）</strong>：</p><ol><li>买 3–5 款直接竞品，看配料表首位是「马铃薯」还是「马铃薯全粉 / 淀粉」——<strong>配料表就能定案，不需要任何内部信息</strong></li><li>顺带记录价格带与净含量，校准本品的定价与人群推测</li><li>同时抓竞品详情页与短视频，看它们的广告怎么打</li></ol><p><strong>成本百元级 + 半天，回报是提案核心主张的地基。</strong> 建议在等物料的空窗期做掉。</p></div><hr><h2 id="四、竞品广告怎么打-→-空白在哪" tabindex="-1">四、竞品广告怎么打 → 空白在哪 <a class="header-anchor" href="#四、竞品广告怎么打-→-空白在哪" aria-label="Permalink to &quot;四、竞品广告怎么打 → 空白在哪&quot;">​</a></h2><table tabindex="0"><thead><tr><th>竞品</th><th>惯用打法</th><th>本品能否跟</th><th>级</th></tr></thead><tbody><tr><td>Jagariko</td><td>轻松办公室 / 校园场景 + 咀嚼音</td><td>场景可借鉴，<strong>日式调性不碰</strong></td><td>B</td></tr><tr><td>品客</td><td>叠罐、潮酷、年轻化</td><td>新品无品牌资产，跟不了</td><td>B</td></tr><tr><td>乐事</td><td>明星代言 + 口味上新</td><td>预算不支持</td><td>B</td></tr><tr><td>可比克</td><td>性价比 + 明星</td><td>杯装成本结构不允许打性价比</td><td>B</td></tr></tbody></table><p><strong>空白地带</strong>：主流薯类广告都在讲<strong>口味</strong>与<strong>代言人</strong>，几乎没有人讲<strong>做法</strong>。</p><div class="tip custom-block"><p class="custom-block-title">这个空白同时解释了机会和成本</p><p>工艺叙事在薯类品类里是低竞争区——这是机会。它之所以空着，一部分原因是<strong>它贵</strong>：需要技术理解、需要合规审校（<a href="./01-proposal">提案第四节</a> 里那一整天）。</p><p><strong>同时它也再次印证了决议 ①</strong>：主位讲做法太重、太慢，观众没耐心；支撑位讲做法刚好填住「为什么脆」的说服缺口。<strong>位置对了，讲做法就从成本变成资产。</strong></p></div><h3 id="番茄味的定位" tabindex="-1">番茄味的定位 <a class="header-anchor" href="#番茄味的定位" aria-label="Permalink to &quot;番茄味的定位&quot;">​</a></h3><p>番茄味是薯类零食的<strong>主流口味</strong>，不是差异点（B）。</p><p><strong>结论</strong>：口味不能作为创意的差异抓手，但<strong>红色是视觉资产</strong>——番茄的红与包装的高饱和橙红是一套，可以在画面上用足。<strong>用其色，不主张其味。</strong></p><hr><h2 id="五、须核实清单" tabindex="-1">五、须核实清单 <a class="header-anchor" href="#五、须核实清单" aria-label="Permalink to &quot;五、须核实清单&quot;">​</a></h2><table tabindex="0"><thead><tr><th>#</th><th>事项</th><th>谁来做</th><th>影响什么</th></tr></thead><tbody><tr><td>1</td><td><strong>直接竞品的配料表首位成分</strong></td><td><strong>我方可自查</strong></td><td>🔴 <strong>决定「原薯鲜切」是不是真差异——最高优先级</strong></td></tr><tr><td>2</td><td>直接竞品价格带与净含量</td><td><strong>我方可自查</strong></td><td>校准人群与场景判断</td></tr><tr><td>3</td><td>本品<strong>建议零售价</strong></td><td>客户</td><td>人群档位、竞品圈层全靠它定。<strong>已并入物料清单第 13 项</strong></td></tr><tr><td>4</td><td>本品<strong>分销渠道</strong>（便利店？集合店？纯电商？）</td><td>客户</td><td>若为纯电商，本文场景推演要大改。<strong>已并入物料清单第 14 项</strong></td></tr><tr><td>5</td><td>客户心中的目标人群与竞品</td><td>客户</td><td>🔴 <strong>客户已口头提过，原话待补入</strong>——补入前本文第一、三节不得作为决策依据</td></tr><tr><td>6</td><td>是否有同系列其他口味 / 规格</td><td>客户</td><td>影响是否要做品类级叙事</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">第 3、4 条已并入物料清单（2026-08-06）</p><p>已作为第 13、14 项写入 <a href="./02-materials">02 · 物料清单</a> 的 🟡 组。</p><p>原因如文中所说：<strong>物料清单原本全是「做片子需要的东西」，缺「决定片子拍什么的东西」</strong>——前者缺了做不出来，后者缺了做出来可能不对，而后一种代价要到成片之后才暴露。</p></div><div class="danger custom-block"><p class="custom-block-title">第 5 项的前提已经不成立</p><p>本文开头写「客户未提供<strong>任何</strong>人群定位与竞品资料」——<strong>这一条是错的</strong>。客户口头提过人群与竞品，原话待补入。</p><p>因此本文中所有标 <strong>C 级 · 待客户校准</strong> 的人群结论，<strong>当前既不能用、也不能确认为错</strong>，必须等原话补入后逐条重判：与客户说法一致的升 A，冲突的以客户为准并重写相关推演。</p><p><strong>在此之前，本文第一、三节不得作为任何创意决策的依据。</strong></p></div><hr><h2 id="三条可以直接用的结论" tabindex="-1">三条可以直接用的结论 <a class="header-anchor" href="#三条可以直接用的结论" aria-label="Permalink to &quot;三条可以直接用的结论&quot;">​</a></h2><ol><li><p>⚠️ <strong>人群是「便利店前站三秒的年轻人」</strong>，不是家庭囤货客——<strong>包装形态自己筛掉了后者</strong>，广告不必去够。<strong>（此条为推演，客户原话补入后需重判）</strong></p></li><li><p><strong>别在「健康」赛道上竞争。</strong> 那里既有合规红线，前面又站着坚果和蛋白零食，本品是天然劣势方。<strong>赛道选口感与场景。</strong></p></li><li><p><strong>花半天买五杯竞品看配料表。</strong> 这是当前唯一不依赖客户、就能推进且直接关系到提案地基的事——<strong>并且它可能推翻决议 ①</strong>。</p></li></ol><hr><p><strong>上一篇</strong> → <a href="./01-proposal">01 · 提案</a> ｜ <strong>下一篇</strong> → <a href="./02-materials">02 · 物料清单</a></p>`,71)])])}const b=r(a,[["render",n]]);export{c as __pageData,b as default};
